/* 100个亲子情境口语：100 场景 / 800 句 / 800 词（紧凑格式：n=编号，t=标题，sub=子分类，lv=难度，w=[[英文，中文]]，s=[[英文，中文]]）*/
var PC_DATA=[{"n":1,"t":"起床","sub":"我的的一天","lv":"初级","w":[["wake up","醒来"],["sleepyhead","懒虫"],["alarm","闹钟"],["awake","醒着的"],["yawn","哈欠"],["stretch","伸展"],["sleep in","睡懒觉"],["make the bed","整理床铺"]],"s":[["It's time to wake up.","该醒来啦。"],["Rise and shine, sleepyhead!","太阳晒屁股了，小懒虫！"],["The alarm is going off.","闹钟响了。"],["Are you awake?","你醒了吗？"],["a big yawn","一个大大的哈欠"],["Stretch your body.","伸展你的身体。"],["No sleeping in today.","今天不能睡懒觉。"],["Don't forget to make the bed.","不要忘记整理床铺。"]]},{"n":2,"t":"洗脸","sub":"我的的一天","lv":"初级","w":[["wash basin","脸盆"],["towel","毛巾"],["wring out","拧干"],["wipe","擦"],["eye booger","眼屎"],["chin","下巴"],["towel rack","毛巾架"],["face cream","面霜"]],"s":[["Fill the wash basin with water.","把脸盆装满水。"],["Get a clean towel and wet it.","拿一块干净的毛巾并把它打湿。"],["Wring out the towel.","拧干毛巾。"],["Let's wipe your forehead and cheeks.","擦擦额头和脸颊。"],["Wipe away your eye boogers.","擦掉你的眼屎。"],["Lift your chin up, so I can wipe the neck.","抬起下巴，让我擦擦脖子。"],["Hang the towel back on the towel rack.","把毛巾挂回毛巾架。"],["Put some cream on your face.","在脸上涂点面霜。"]]},{"n":3,"t":"刷牙","sub":"我的的一天","lv":"初级","w":[["toothbrush","牙刷"],["toothpaste","牙膏"],["cup","杯子"],["mouth","嘴巴"],["brush","刷"],["rinse","漱口"],["tooth decay","蛀牙"],["spit","吐"]],"s":[["Wet the toothbrush.","把牙刷弄湿。"],["Squeeze some toothpaste on the toothbrush.","在牙刷上挤一点牙膏。"],["Put some water in the cup.","杯子里放些水。"],["Open your mouth wide.","把嘴巴张大。"],["Brush up and down, round and round.","上下刷，打圈圈刷。"],["Rinse your mouth.","漱漱口。"],["Brushing your teeth well can help prevent tooth decay.","好好刷牙可以预防蛀牙。"],["Spit out the water.","把水吐出来。"]]},{"n":4,"t":"换尿不湿","sub":"我的的一天","lv":"中级","w":[["diaper","尿不湿"],["leak","渗漏"],["take off","脱掉"],["baby wipes","婴儿湿巾"],["diaper rash cream","护臀霜"],["tape","胶带"],["edge","边"],["roll up","卷起"]],"s":[["It's time to change your diaper.","该换尿不湿了。"],["Your diaper is leaking.","你的尿不湿漏了。"],["Lie down and stay still. Let me take off your dirty diaper.","躺下别动，让我来脱掉尿不湿。"],["Lift up your bottom a little and clean your bottom with baby wipes.","稍微抬起你的小屁屁，用婴儿湿巾擦一擦。"],["Oh no! You have a diaper rash. Apply some diaper rash cream.","哎呀，你起尿布疹了！抹点护臀霜吧。"],["Wrap the new diaper around your bottom and fasten both sides with the tape.","用新的尿不湿包住小屁屁，粘紧两侧粘扣。"],["Pull out the edge of the diaper.","把尿不湿的边拉出来。"],["Roll up the dirty diaper and throw it in the trash bin.","把脏尿不湿卷起来扔进垃圾桶。"]]},{"n":5,"t":"梳头发","sub":"我的的一天","lv":"初级","w":[["comb / brush","梳子"],["tangled up","打结"],["hairstyle","发型"],["ponytail","马尾辫"],["braid","编成辫子"],["hair tie","发绳"],["hair clip","发夹"],["hair band","发箍"]],"s":[["Let's comb / brush your hair.","我们来梳头发吧。"],["Your hair is tangled up.","你的头发打结了。"],["What kind of hairstyle do you want today?","你今天想梳什么样的发型呢？"],["Do you want to tie it in a ponytail?","你想扎成马尾辫吗？"],["Let's braid the hair into pigtails.","我们把头发编成两条辫子吧。"],["Can you pass me a hair tie?","你可以把发绳递给我吗？"],["Which hair clip do you want?","你想要哪个发夹？"],["Let's wear a hair band to keep your hair away from your face.","我们戴个发箍吧，免得头发挡住脸。"]]},{"n":6,"t":"洗头发","sub":"我的的一天","lv":"初级","w":[["greasy","油腻的"],["shampoo","洗发水"],["foam","泡沫"],["massage","按摩"],["scratch","抓挠"],["rinse off","冲洗"],["wrap","包、裹"],["hairdryer","电吹风"]],"s":[["Your hair looks so greasy.","你的头发看起来很油腻。"],["Put some shampoo on your hair.","在头发上涂一些洗发水。"],["Let's make some foam with the shampoo.","把洗发水搓出泡泡。"],["Massage the scalp softly.","轻轻按摩头皮。"],["Don't scratch with your nails too hard.","不要用指甲用力抓。"],["Let's rinse the shampoo off.","让我们把洗发水冲洗掉。"],["Wrap your hair with a towel.","用毛巾包裹住头发。"],["Use the hairdryer to dry your hair.","用电吹风吹干头发。"]]},{"n":7,"t":"洗澡","sub":"我的的一天","lv":"初级","w":[["bath / shower","洗澡"],["bathtub","浴缸"],["adjust","调整"],["body wash","沐浴露"],["scrub","擦洗"],["armpit","腋窝"],["wash off","冲洗"],["dry off","弄干"]],"s":[["Are you ready for a bath / shower?","你准备好洗澡了吗？"],["Let's fill the bathtub with water.","让我们把浴缸装满水。"],["Adjust the water temperature first.","先调节水温。"],["Let's get some body wash.","抹点沐浴露。"],["Scrub everywhere all over your body.","把全身都擦洗一遍。"],["Wash your armpits, too.","腋窝也要洗到哦。"],["Now wash off with water.","现在用水冲洗掉。"],["Let me dry you off with the towel.","让我用毛巾把你擦干吧。"]]},{"n":8,"t":"洗手","sub":"我的的一天","lv":"中级","w":[["faucet","水龙头"],["palm","手掌"],["rub","揉擦"],["finger","手指"],["interlock","扣紧"],["fingertip","指尖"],["thumb","拇指"],["wrist","手腕"]],"s":[["Turn on the faucet and wet your hands.","打开水龙头，把手弄湿。"],["Apply some soap to your hands and rub your palms together.","打上肥皂，手掌相对搓一搓。"],["Rub the back of your hands and fingers.","搓搓手背和手指。"],["Rub in between your fingers.","搓一搓指缝。"],["Interlock fingers and rub the back of fingers of both hands.","十指紧扣，搓搓双手手指背。"],["Rub fingertips on palm of the other hand in circle manner, then switch.","指尖放在另一只手心上打圈搓，然后换手搓。"],["Hold the thumb and rub it in rotating manner.","握住拇指以旋转的方式搓洗。"],["Rub both wrists in rotating manner, then rinse off the soap.","以旋转的方式搓洗双手腕，然后把肥皂冲洗掉。"]]},{"n":9,"t":"剪指甲","sub":"我的的一天","lv":"初级","w":[["nail","指甲"],["trim","修剪"],["nail clipper","指甲钳"],["move","移动"],["hangnail","倒刺"],["nail file","指甲锉"],["switch","调换"],["bite","咬"]],"s":[["Your nails are getting long.","你的指甲变长了。"],["It's time to trim your nails.","是时候剪指甲了。"],["Let's get a nail clipper.","我们拿个指甲钳。"],["Don't move, we'll be finished soon.","不要动，我们很快就会剪完。"],["Don't use your hand to pull the hangnail off, let's cut it off.","不要用手去拔倒刺，让我们把它剪掉。"],["We can use the nail file to make the nails more smooth.","让我们用指甲锉使指甲更光滑。"],["We've already done with this hand. Now switch the other hand.","这只手剪完了，现在换另一只手。"],["Don't bite your nails, they are full of germs.","不要咬指甲，指甲里都是细菌。"]]},{"n":10,"t":"冲奶粉","sub":"我的的一天","lv":"初级","w":[["pour","倒"],["scale","刻度"],["formula","配方奶粉"],["scoop","勺子"],["level off","把…弄平"],["screw","旋拧"],["shake","摇动"],["drip","滴下"]],"s":[["First let's pour some warm water into the bottle.","先往瓶子里倒点温水。"],["Let me check the scale, we need 200 milliliters.","查看一下刻度，我们需要200毫升水。"],["Now we can add the formula.","现在我们可以加奶粉了。"],["Open the lid and take out the scoop.","打开盖子，取出勺子。"],["Level off each scoop.","每一勺都要刮平哦。"],["Screw the cap on tight.","拧紧瓶盖。"],["Shake well to mix it all up.","充分摇匀。"],["Drip a few drops on the wrist to check the temperature.","在手腕上滴几滴来检查一下温度。"]]},{"n":11,"t":"穿衣服","sub":"我的的一天","lv":"初级","w":[["pick out","挑选出"],["get dressed","穿衣服"],["put in","把…放进去"],["through","穿过"],["put on","穿上"],["pull","拉"],["button","纽扣"],["zip","拉链"]],"s":[["Pick out what you want to wear today.","挑选你今天想穿的衣服吧。"],["Let's get dressed.","我们来穿衣服吧。"],["Put your head in.","把头伸进去。"],["Arms through.","把胳膊穿过去。"],["Now put on your pants.","现在来穿上裤子。"],["Stand up and pull it over your bottom.","站起来把裤子提到屁股上方。"],["Let's do the buttons.","我们来扣好纽扣。"],["Zip up the jacket.","拉上夹克拉链。"]]},{"n":12,"t":"衣服穿反","sub":"我的的一天","lv":"中级","w":[["on backwards","穿反"],["inside out","内外翻转"],["button","纽扣"],["zipper","拉链"],["stick out","外露"],["skewed","歪斜的"],["match","匹配"],["swap","交换"]],"s":[["You've got your shirt on backwards. Take it off and turn it around.","你的衬衫穿反了，脱下来转个面吧。"],["You are wearing your T-shirt inside out. Let's flip it right side out.","你的T恤穿反了，把它翻过来，正确面朝外吧。"],["You have your buttons in the wrong holes.","你的扣子系错位置了。"],["The zipper got stuck.","拉链卡住了。"],["Your underpants are sticking out. Let's pull them down a bit.","你的内裤露出来了，我们把它往下拉一点。"],["Your pants are skewed. Let me fix them for you.","你的裤子有点歪了，我帮你弄直。"],["Your socks don't match. Let's pair them up.","你的袜子不是一对，我们来把它们配成一对吧。"],["Your shoes are on the wrong feet. Let's swap them.","你的鞋子穿反了，把它们换过来吧。"]]},{"n":13,"t":"穿袜子","sub":"我的的一天","lv":"中级","w":[["sock","袜子"],["heel","脚后跟"],["toe","脚趾"],["scrunch up","揉成一团"],["opening","开口"],["pull up","拉上"],["crooked","歪的"],["a pair","一双"]],"s":[["Let mommy show you how to put on your socks.","让妈妈教你如何穿袜子吧。"],["Make sure the heels are facing down.","确保脚后跟朝下。"],["Lift your foot up, toes in the air.","抬起你的脚，让脚趾朝上。"],["Scrunch up your sock like this.","像这样把袜子堆叠起来。"],["Stretch the opening and put it over your toes.","把袜口撑大，裹住脚趾。"],["Pull it up towards your body until it fully covers your foot.","朝身体方向往上拉直到完全覆盖住你的脚。"],["It's a little crooked. Let me help you straighten it out.","有点歪了，让我帮你把它弄直。"],["These two socks are not a pair.","这两只袜子不是一双。"]]},{"n":14,"t":"穿鞋子","sub":"我的的一天","lv":"初级","w":[["shoe rack","鞋架"],["sneakers","运动鞋"],["Velcro","魔术贴"],["slide into","滑进"],["back of the shoe","鞋后跟"],["tongue of the shoe","鞋舌"],["tie shoelaces","系鞋带"],["on the wrong feet","鞋子穿反了"]],"s":[["Get your shoes from the shoe rack.","去鞋架上拿你的鞋子。"],["Put on your sneakers.","穿上运动鞋。"],["Undo the Velcro.","打开魔术贴。"],["Slide your feet into the shoes.","把脚伸进鞋子。"],["Pull out the back of the shoe.","把鞋后跟拽出来。"],["Pull out the tongue of the shoe.","把鞋舌拉出来。"],["Can you do the Velcro / tie shoelaces?","你会扣魔术贴/系鞋带吗？"],["Your shoes are on the wrong feet, switch them.","你的鞋子穿反了，换一下。"]]},{"n":15,"t":"系鞋带","sub":"我的的一天","lv":"初级","w":[["tie one's shoes","系鞋带"],["pull on","拉紧"],["knot","结"],["loop","环状物"],["criss-cross","十字交叉"],["hole","洞"],["pull out","拉出"],["bowknot","蝴蝶结"]],"s":[["Sweetie, can you tie your shoes?","宝贝，你会系鞋带吗？"],["Pull on the laces and cross them to make an X.","拉紧鞋带，交叉打成一个X字。"],["Put one lace under the other and pull to tie a basic knot.","把一根鞋带放在另一根下面，然后拉紧打个基本的结。"],["Then make two loops.","然后打两个圈圈。"],["Criss-cross the loops.","把这两个环十字交叉。"],["Put one loop through the hole.","把一个环穿过洞。"],["Pull out the loop and tighten the laces.","拉出环并收紧鞋带。"],["Look, a nice bowknot. Do you want to have a try?","看，一个漂亮的蝴蝶结。你要试试吗？"]]},{"n":16,"t":"换拖鞋","sub":"我的的一天","lv":"初级","w":[["slipper","拖鞋"],["change into","换上"],["shoe cabinet","鞋柜"],["take out","取出"],["take off","脱下"],["slip on","快速穿上"],["trip and fall","绊倒"],["barefoot","赤脚的/地"]],"s":[["a pair of slippers","一双拖鞋"],["Change into your slippers when you get home.","回家换上拖鞋。"],["Your slippers are in the shoe cabinet.","你的拖鞋在鞋柜里。"],["Open it and take out your slippers.","打开鞋柜取出拖鞋。"],["Take off your shoes.","脱下你的鞋子。"],["Slip on your slippers.","穿上拖鞋。"],["Running with slippers might make you trip and fall.","穿着拖鞋跑可能会让你绊倒。"],["Don't walk barefoot.","不要赤着脚走。"]]},{"n":17,"t":"睡觉","sub":"我的的一天","lv":"初级","w":[["pajamas","睡衣"],["lie down","躺下"],["pillow","枕头"],["tummy","肚子"],["tuck...in","把…的被子掖好"],["kick off","踢掉"],["toss and turn","翻来覆去"],["good night","晚安"]],"s":[["Change into your pajamas.","换上你的睡衣。"],["Now lie down on your bed.","现在躺到床上。"],["Put your head on the pillow.","把头放在枕头上。"],["Don't sleep on your tummy, try to sleep on your back.","不要趴着睡，尽量平躺着睡。"],["Let mommy tuck you in.","妈妈帮你把被子盖好。"],["Don't kick off the blanket.","不要踢被子哦。"],["Lie still, stop tossing and turning.","躺好啦，不要翻来翻去。"],["Good night, have a nice dream.","晚安，做个好梦。"]]},{"n":18,"t":"量身高","sub":"我的的一天","lv":"中级","w":[["measure one's height","量身高"],["straight","笔直的"],["popsicle","冰棍"],["move","移动"],["tiptoe","踮脚"],["look up","抬头"],["measuring tape","卷尺"],["grow","成长"]],"s":[["Let's measure your height to see how tall you are.","我们来量量身高，看看你长多高了。"],["Stand up straight and keep your back flat against the wall.","站直，背部平靠着墙。"],["Can you pretend to be a popsicle?","你能假装是一根冰棍吗？"],["Don't move. Let's see how long you can stand without melting.","不要动，看看你能站多久不融化呢？"],["Don't stand on tiptoe.","不要踮脚。"],["Look ahead, don't look up.","向前看，不要抬头。"],["Pull out the measuring tape and measure from your toes to the top of your head.","拉出卷尺，从你脚趾开始测量到你的头顶。"],["You are 115 cm tall, and you've grown a lot.","你身高115厘米，长高了很多哦。"]]},{"n":19,"t":"称体重","sub":"我的的一天","lv":"中级","w":[["weigh","称体重"],["scale","秤"],["in the middle","在中间"],["wooden person","木头人"],["flash","闪烁"],["heavier than","比…重"],["weight","重量"],["strong","健壮的"]],"s":[["Let's see how much you weigh.","让我们来看看你有多重了。"],["Take off your shoes and step on the scale.","脱掉鞋子，站在体重秤上。"],["Stand in the middle. Don't touch or hold on to anything.","站在中间，不要碰或抓住任何东西。"],["Pretend to be a little wooden person who can't move.","假装是个不能动的小木头人。"],["Keep still until the number stops flashing.","保持不动直到数字停止闪烁。"],["Let's see if you are heavier than an elephant.","看看你是不是比大象还重呢。"],["This number is your weight. You are 11.2 kilograms.","这个数字就是你的体重。你11.2公斤重哦。"],["Keep it up. You'll grow big and strong.","坚持下去，你会变得又高又壮。"]]},{"n":20,"t":"上厕所","sub":"我的的一天","lv":"初级","w":[["poop","屎"],["pee","尿"],["toilet lid","马桶盖"],["pull down","拉下"],["potty","便盆"],["toilet paper","厕纸"],["bottom","屁股"],["flush","冲洗"]],"s":[["Do you need to poop?","你想拉屎吗？"],["Don't hold your pee, it'll hurt.","不要憋尿，会很难受。"],["Lift up the toilet lid.","掀开马桶盖。"],["Pull down your pants and underwear to your knees.","把裤子和内裤脱到膝盖就行。"],["Now sit on the potty / toilet seat.","现在坐在马桶上。"],["Get some toilet paper and fold it up.","拿一些厕纸，折起来。"],["Put your tummy on my legs and bend over with your bottom out.","趴在我的腿上然后弯腰，小屁屁露出来。"],["Don't forget to flush the toilet and wash your hands.","别忘了冲马桶和洗手哦。"]]},{"n":21,"t":"吃早餐","sub":"我的的一天","lv":"初级","w":[["breakfast","早餐"],["highchair","高脚椅"],["cool off","变凉"],["chew","咀嚼"],["spoon","勺子"],["mouth full","满嘴"],["full","饱的"],["napkin","餐巾纸"]],"s":[["Breakfast is ready, come and enjoy it.","早餐准备好啦，快来吃吧。"],["Sit on your highchair and put on your bib.","坐上你的高脚椅，戴上围兜。"],["It's still hot. Blow on it to cool it off.","还很烫，吹一吹使它冷却。"],["Chew it well before you swallow it.","充分咀嚼再咽下去。"],["Use the spoon instead of your hands.","不要用手，用勺子。"],["Don't talk with your mouth full.","不要边吃边说话。"],["Are you full? Would you like some more?","吃饱了吗？还想要一些吗？"],["Wipe your mouth with the napkin.","用餐巾纸擦擦嘴巴。"]]},{"n":22,"t":"吃面条","sub":"我的的一天","lv":"初级","w":[["noodles","面条"],["soggy","湿而软的"],["chopsticks","筷子"],["twirl","旋转"],["lift","举起"],["blow","吹"],["slurp","大声啜喝"],["soup","汤"]],"s":[["Beef noodles are ready.","牛肉面条已经做好了。"],["Let's tuck in, or the noodles will get soggy.","我们快点吃吧，不然面条就烂了。"],["Pick up the noodles with chopsticks.","用筷子夹起面条。"],["Twirl the noodles around the chopsticks.","用筷子把面条卷起来。"],["Lift them up to your mouth.","把面条送到嘴边。"],["Blow on them. They are hot.","吹一吹，还很烫。"],["Don't slurp your noodles.","别吸溜面条。"],["Have some soup, too.","喝点汤。"]]},{"n":23,"t":"喝水","sub":"我的的一天","lv":"初级","w":[["thirsty","口渴的"],["drink","喝"],["sip","一小口"],["gulp","大口吞食"],["choke","呛到"],["straw","吸管"],["more","更多的"],["go to bed","睡觉"]],"s":[["Are you thirsty?","你口渴了吗？"],["Let's drink some water.","我们喝点水吧。"],["Take small sips.","小口喝水。"],["Don't gulp it down.","不要大口喝。"],["If you drink too fast, you are gonna choke.","如果你喝得太快，会被呛到的。"],["You can use a straw to drink.","你可以用吸管喝。"],["Have some more.","再喝一点吧。"],["Try not to drink too much water before going to bed.","睡前不要喝太多水。"]]},{"n":24,"t":"吃零食","sub":"我的的一天","lv":"初级","w":[["snack","零食"],["too much","太多"],["stomach","胃"],["share","分享"],["eat up","吃完"],["one more","再一个"],["wipe","擦拭"],["expired","过期的"]],"s":[["I'm hungry. Can I have a snack?","我饿了。可以吃点零食吗？"],["Sure. But don't eat too much.","当然可以。不过别吃太多。"],["Save some room in your stomach. We still have dinner tonight.","留点空间给你的胃，我们还要吃晚餐呢。"],["Would you like to share with mommy?","你愿意和妈妈分享一下吗？"],["Don't eat it all up, leave some for next time.","不要都吃完，留下次再吃。"],["Just one more, OK?","再来一块，可以吗？"],["Don't lick your fingers after eating, use a tissue to wipe them.","吃完不要舔手指，用纸巾擦一擦。"],["The cookies are expired. Go throw them out.","这些饼干已经过期了，丢掉吧。"]]},{"n":25,"t":"擤鼻涕","sub":"我的的一天","lv":"初级","w":[["running nose","流鼻涕"],["wipe","擦"],["sniff","抽鼻涕"],["tissue","纸巾"],["nostril","鼻孔"],["the other side","另一侧"],["crumple up","揉成一团"],["trash can","垃圾桶"]],"s":[["You have a running nose.","你流鼻涕了。"],["Don't wipe your nose with your hand.","不要用你的手擦鼻涕。"],["Don't sniff back your snot.","别把鼻涕吸回去。"],["Take a tissue and put it onto your nose.","拿一张纸巾放在鼻子上。"],["Press onto your right nostril. Blow through your other nostril into the tissue.","将纸巾压在右鼻孔上，然后通过另一个鼻孔擤到纸巾上。"],["Do the same with the other side.","另一侧也这样擦。"],["Wipe your nose, then crumple up the tissue.","擦擦鼻子，然后把纸巾揉成一团。"],["Throw it into the trash can and wash your hands.","将用过的纸巾扔进垃圾桶，然后洗手。"]]},{"n":26,"t":"蚊子咬","sub":"我的的一天","lv":"中级","w":[["mosquito","蚊子"],["bump","肿块"],["itchy","痒的"],["scratch","抓、挠"],["anti-itch cream","止痒膏"],["mosquito repellent","驱蚊剂"],["mosquito swatter","电蚊拍"],["mosquito net","蚊帐"]],"s":[["I've got a mosquito bite on the leg.","我腿上被蚊子咬了。"],["The mosquito bite will give you a little bump on your skin.","蚊子叮咬会在你的皮肤上叮出一个小包。"],["The mosquito bites are so itchy!","蚊子包好痒啊！"],["Try not to scratch the mosquito bite, or it'll get worse.","尽量不要抓蚊子包，否则情况会更糟糕。"],["Let's apply some anti-itch cream to relieve the itch.","我们抹点止痒膏来缓解瘙痒吧。"],["Let's spray some mosquito repellent to keep the mosquitoes away.","喷点驱蚊水让蚊子远离。"],["The mosquito swatter uses electricity to zap the mosquitoes.","电蚊拍用电来击杀蚊子。"],["Sleeping inside a mosquito net can prevent mosquito bites.","在蚊帐里睡觉可以避免蚊子咬。"]]},{"n":27,"t":"受伤","sub":"我的的一天","lv":"中级","w":[["bump","肿块"],["bruise","淤青"],["scrape","擦伤"],["iodine","碘酒"],["hang in","坚持"],["band-aid","创口贴"],["scab","结痂"],["heal up","愈合"]],"s":[["You got a bump on your head. The ice pack will help keep the swelling down.","你头上撞了个包。冰袋可以减轻肿胀。"],["You have a bruise. Don't worry, the colors will fade away gradually.","你手背淤青了。不要担心，颜色会逐渐退去。"],["You have a scrape on your knee. It's bleeding!","你的膝盖擦伤了。在流血！"],["First use iodine to disinfect it.","先用碘酒消消毒。"],["It's gonna sting a little bit. Hang in there, brave boy!","会有一点点的刺痛。坚持住，勇敢的孩子！"],["Now let's put a band-aid on it.","现在我们贴个创口贴吧。"],["It'll turn into a scab. Remember not to pick the scab.","它会结痂的。不要去抠痂。"],["You'll heal up very soon.","你很快就会痊愈的。"]]},{"n":28,"t":"用电安全","sub":"我的的一天","lv":"中级","w":[["outlet","插座"],["plug","插头"],["unplug","拔插头"],["cord","电线"],["switch","开关"],["electrical appliance","电器"],["electric shock","触电"],["charge","充电"]],"s":[["Never touch the outlets on the wall. It's dangerous.","不要摸墙上的插座，很危险。"],["Only plugs go into the outlet, nothing else.","只有插头能通过插孔，其他东西都不行。"],["Always turn off the equipment before you unplug it.","拔插头前先关设备。"],["When you unplug something, hold the plug, not the cord.","拔下东西时握住插头而不是电线。"],["Do not touch any plugs or switches with wet hands.","手湿的时候不要摸插头或开关。"],["Don't put any electrical appliances close to water.","不要把任何电器放在靠近水的地方。"],["When electricity travels through our body, we'll get electric shock.","当电流通过我们的身体时，我们会触电。"],["Let mommy know if the toy is out of battery. Don't charge it by yourself.","如果玩具没电了，告诉妈妈。不要自己给它充电。"]]},{"n":29,"t":"搭积木","sub":"游戏玩耍","lv":"中级","w":[["build blocks","搭积木"],["line","排、列"],["stack up","堆积"],["off balance","失去平衡"],["tower","塔"],["top off","用…完成"],["knock over","打翻"],["put away","收起、放好"]],"s":[["Let's build blocks.","我们来搭积木吧。"],["Can you place them in a long line?","你能把它们排成一排吗？"],["Let's try to stack up the blocks neatly.","我们试着把积木整齐地堆叠起来吧。"],["If the blocks are off balance, they'll fall down.","如果积木不平衡，就会倒下。"],["Let's build a tower with these blocks.","我们用这些积木搭塔吧。"],["Three squares for the base. Two rectangles to make it taller. One triangle to top it off.","底部用三个正方形。上面是两个长方形。顶部用一个三角形。"],["You knock over the blocks. It's OK, we can try again.","积木被推翻了。没关系，我们再拼一次。"],["We should put the blocks away when we are done playing.","我们玩好之后要把积木收起来。"]]},{"n":30,"t":"玩乐高","sub":"游戏玩耍","lv":"初级","w":[["Lego","乐高"],["instruction manual","说明书"],["stud","凸起"],["push down","按压"],["upside down","颠倒"],["fix","修理"],["no rush","别着急"],["take apart","拆开"]],"s":[["Look, I've got a new Lego set for you.","看，我给你买了一套新的乐高玩具。"],["Let's check the instruction manual.","让我们查看一下说明书。"],["Make sure the studs fit into the hole.","凸起要对准洞洞。"],["Push it down hard to make sure it's stable.","用力按下去确保它稳固。"],["It's upside down. Let's turn it over.","颠倒了，我们把它翻过来。"],["We made a mistake, let's fix it.","我们犯了个错误，把它改过来。"],["Take your time, no rush.","别着急，慢慢来。"],["Now let's take them apart and build something new.","现在把它们拆开，拼个新的东西。"]]},{"n":31,"t":"拼图","sub":"游戏玩耍","lv":"初级","w":[["puzzle","拼图"],["dump out","倒出"],["flip","翻转"],["sort","把……分类"],["frame","边框"],["match","匹配"],["rotate","旋转"],["high five","击掌"]],"s":[["Let's do the puzzle.","我们来玩拼图吧。"],["Dump out all the pieces and spread them out.","把所有的碎片都倒出来，然后摊开。"],["Flip all the pieces face up.","把所有的碎片翻成正面。"],["Sort out all the edge pieces and corner pieces from the inside pieces.","把所有的边角块从内部块中挑出来。"],["Let's start with the frame first.","我们先拼边框吧。"],["These two don't match.","这两片不匹配。"],["Try to rotate it, and press the tab into the slot.","试着旋转一下，然后把凸起按进插槽中。"],["You made it. High five!","你成功了，击个掌吧！"]]},{"n":32,"t":"玩橡皮泥","sub":"游戏玩耍","lv":"初级","w":[["play dough","橡皮泥"],["squeeze","挤压"],["roll","滚动"],["stretch","拉伸"],["squish","压扁"],["pinch","捏"],["shape cutter","形状模具"],["dry","干的"]],"s":[["Let's play with play dough / clay.","我们玩橡皮泥/黏土吧。"],["You can squeeze it. It's soft and squishy.","你可以挤压橡皮泥，它软软的、黏黏的。"],["Roll it into a ball with your hands.","用手把它滚成球形。"],["Stretch it into a long piece.","把它拉成长条。"],["Gently squish it.","轻轻地压扁。"],["Use your fingers to pinch.","用手指捏一捏。"],["Put the shape cutter on top of it, then push down.","把模具放在上面，然后压下去。"],["Put the lid back on after playing, or it'll get dry.","玩好之后盖上盖子，否则它会干的。"]]},{"n":33,"t":"剪纸","sub":"游戏玩耍","lv":"中级","w":[["paper cutting","剪纸"],["scissors","剪刀"],["thumb","大拇指"],["open up","打开"],["dashed line","虚线"],["push forward","往前推"],["bits of paper","纸屑"],["run","跑"]],"s":[["Let's do some paper cutting.","我们来剪纸吧。"],["This is a pair of scissors.","这是一把剪刀。"],["Put your thumb in this hole, and the rest of your fingers in the other hole.","把你的大拇指放进这个洞里，其余的手指放进另一个洞。"],["Let's open them up and close them on the paper.","打开剪刀，然后在纸上合上它们。"],["Cut along the dashed line. Watch your fingers.","沿着虚线剪。小心手指。"],["Push the scissors forward and turn the paper.","把剪刀往前推，然后转动纸张。"],["When you are done cutting, throw the bits of paper away.","剪完之后，把这些纸屑扔掉。"],["Don't run with your scissors. You might get hurt.","不要拿着剪刀跑，你可能会受伤。"]]},{"n":34,"t":"画画","sub":"游戏玩耍","lv":"中级","w":[["draw","画画"],["color","给……涂颜色"],["fill","填满"],["in","在…内"],["paint","颜料"],["paintbrush","画笔"],["wash off","清洗"],["mix","混合"]],"s":[["Let's draw a cat. Can you draw it by yourself?","我们来画一只猫。你能自己画吗？"],["Would you like to color it with the markers, crayons or colored pencils?","你想用马克笔、蜡笔或彩色铅笔给它上色吗？"],["Color next to the black line first, then fill in the middle.","沿着黑色线条先涂上颜色，然后再填满中间部分。"],["Up and down, side to side, and stay in the line.","上下左右，涂在线里面。"],["We can also squeeze some paint onto the palette.","我们还可以挤些颜料到颜料盘上。"],["Dip the paintbrush in the paint and paint on the paper.","用画笔蘸点颜料，然后在纸上绘画。"],["When you want to change colors, wash off the paintbrush first.","当你想换颜色时，先清洗画笔。"],["You can mix the colors to create a new color.","你可以混合不同的颜色来创造出新的颜色。"]]},{"n":35,"t":"医生游戏","sub":"游戏玩耍","lv":"初级","w":[["doctor","医生"],["patient","病人"],["stethoscope","听诊器"],["open","打开"],["take one's temperature","量体温"],["have a fever","发烧"],["give a shot","打针"],["medicine","药物"]],"s":[["Let's play doctor.","我们来玩医生游戏吧。"],["Teddy bear is our patient. It's feeling sick.","泰迪熊是我们的病人。它感觉不舒服。"],["Use the stethoscope to check the heartbeat.","用听诊器检查心跳。"],["Open your mouth wide and say \"ah\".","张大嘴巴，说“啊”。"],["Let me take your temperature with the thermometer.","让我用体温计给你量一下体温。"],["You have a fever.","你发烧了。"],["Let me give you a shot. It's gonna sting a little bit.","让我给你打一针。会有一点点疼哦。"],["Take this medicine twice a day for 3 days. Don't worry, you'll be fine soon.","这个药一天吃两次，连续吃三天。别担心，你很快就会好起来的。"]]},{"n":36,"t":"过家家","sub":"游戏玩耍","lv":"初级","w":[["play house","过家家"],["hungry","饿的"],["apron","围裙"],["chop","切碎"],["pan","平底锅"],["sprinkle","撒"],["wait a minute","等一下"],["serve","端上"]],"s":[["Let's play house.","我们玩过家家吧。"],["Mommy will be the baby. I'm hungry now.","妈妈来当宝宝。我现在饿了。"],["Put on an apron.","穿上围裙。"],["Chop the vegetable on the board.","把蔬菜放在案板上切碎。"],["Put them in the pan and turn on the stove.","把它们放入平底锅，打开炉灶。"],["Use the spatula to stir and sprinkle some salt.","用锅铲搅拌并撒些盐。"],["Wait a minute, the food is almost ready.","再等一下，饭快做好了。"],["The food is ready to serve. Grab the plate and put food on it.","食物已经好了，拿个盘子，把食物放在上面吧。"]]},{"n":37,"t":"捉迷藏","sub":"游戏玩耍","lv":"初级","w":[["hide-and-seek","捉迷藏"],["seeker","寻找者"],["count","数数"],["peek","偷看"],["ready","准备好"],["where","哪里"],["behind","在……的后面"],["found","找到"]],"s":[["Let's play hide-and-seek.","我们来玩捉迷藏吧。"],["I'm gonna be the seeker and you are the hider.","我将是寻找者，你是隐藏者。"],["Now I'll count to five.","现在我会数到5。"],["Hey, mom! No peeking.","嘿，妈妈！不许偷看。"],["Ready or not, here I come.","不管你藏没藏好，我都开始找咯。"],["Where is my baby hiding?","我的宝宝藏在哪里呢？"],["Is she hiding behind the curtain?","她藏在窗帘后面吗？"],["I found you!","我找到你啦。"]]},{"n":38,"t":"骑自行车","sub":"游戏玩耍","lv":"中级","w":[["helmet","头盔"],["handlebar","把手"],["balance","平衡"],["direction","方向"],["brake","刹车"],["bell","铃"],["training wheel","辅助轮"],["inflate","充气"]],"s":[["Put on the helmet. It'll protect your head from getting hurt.","戴上头盔。它能保护你的头部不受伤害。"],["Hold onto the handlebars and get on the bike. Then start pedaling.","握住把手上车。然后开始蹬踏板。"],["Look ahead. Try to keep your balance.","向前看。尽量保持平衡。"],["Turn the handlebars to change directions.","转动把手来改变方向。"],["When you need to slow down or stop, just squeeze the brakes.","当你需要减速或者停车时，只需握紧刹车。"],["If someone is in your way, you can ring the bell to remind them.","如果有人挡道了，你可以按铃来提醒他们。"],["Training wheels can make it easier for you to ride the bike.","辅助轮可以让你更容易骑自行车。"],["Your tire is flat. Let's inflate it with a pump.","你的轮胎瘪了。我们用打气筒给它打点气吧。"]]},{"n":39,"t":"骑扭扭车","sub":"游戏玩耍","lv":"中级","w":[["wiggle car","扭扭车"],["deck","甲板"],["steering wheel","方向盘"],["move forward","前进"],["push","推"],["slow down","减速"],["U turn","掉头"],["fast","快速的"]],"s":[["Do you know how to ride your wiggle car?","你知道怎么骑扭扭车吗？"],["Sit on it and put your feet on the deck.","坐上去，把脚放在踏板上。"],["Hold the steering wheel tight and keep balanced.","紧握方向盘，保持平衡。"],["Turn the steering wheel left and right to make the wiggle car move forward.","左右转动方向盘，让扭扭车向前移动。"],["You can also push with your feet.","你也可以用脚来推。"],["Use your feet to slow down or stop.","把脚放在地上减速或停下。"],["Make a U turn and come back.","掉头回来。"],["Be careful not to ride too fast.","小心不要骑太快。"]]},{"n":40,"t":"骑滑板车","sub":"游戏玩耍","lv":"中级","w":[["scooter","滑板车"],["grip","握紧"],["push off","蹬地"],["fall down","摔倒"],["brake","刹车"],["bump","碰撞"],["glide","滑行"],["deck","滑板"]],"s":[["Do you want to ride your scooter?","你想骑滑板车吗？"],["Grip the handlebars with both hands.","双手握住车把。"],["Keep one foot on the deck and push off the ground with the other foot.","一只脚放在滑板上，用另一只脚蹬地。"],["Keep yourself balanced and try not to fall down.","保持平衡不要摔倒。"],["You can step on the brake to slow down or stop.","你可以踩刹车来减速或停下来。"],["Keep your eyes in front of you. Don't bump into anything.","眼睛看前面。不要撞到任何东西。"],["Push, push, glide.","蹬，蹬，滑行。"],["Once you have your balance and speed up, you can move the kicking leg onto the deck, too.","等你掌握了平衡并且加速了，蹬地的那条腿也可以放到滑板上。"]]},{"n":41,"t":"荡秋千","sub":"游戏玩耍","lv":"中级","w":[["swing","摇摆，秋千"],["both sides","两边"],["worry","担心"],["push","推"],["by yourself","你自己"],["touch the ground","触地"],["get off","下来"],["jump off","跳下来"]],"s":[["Let's go swinging on the swing.","我们去荡秋千吧。"],["Hold on tight to both sides. Don't let go.","紧紧抓住两边，不要松手。"],["Don't worry, mommy will push you gently.","别担心，妈妈会轻轻地推你。"],["We are swinging. Do you want to go higher? I'm gonna give you a big push.","我们在荡秋千。你想更高吗？妈妈给你一个大推力。"],["Do you want to swing by yourself? Kick your feet up, then tuck your feet back in.","你想自己荡秋千吗？把脚抬起来，然后再把脚收回来。"],["Try not to let your feet touch the ground.","脚尽量不要碰到地面。"],["Let me know if you want to get off.","如果你想下来，告诉我。"],["It's dangerous to jump off, so wait for the swing to stop.","从上面跳下来很危险，所以请等秋千停下来后再下来。"]]},{"n":42,"t":"滑滑梯","sub":"游戏玩耍","lv":"中级","w":[["slide","滑梯"],["step by step","一步一步地"],["slide down","滑下"],["afraid","害怕的"],["on your tummy","趴着"],["head first","头朝前地"],["as soon as","一……就……"],["climb up","爬上"]],"s":[["Let's play on the slide.","我们去玩滑梯吧。"],["Hold onto the handrail. Go up the stairs step by step.","握住扶手，一步一步从楼梯上去。"],["Sit at the top of the slide, then slide down on your bottom.","坐在滑梯顶端，然后用屁股滑下来。"],["Don't be afraid, mommy will catch you at the bottom.","不要害怕，妈妈会在下面接住你的。"],["Wanna slide down on your tummy?","你想趴着滑吗？"],["Remember not to slide down head first.","记住不要头朝下滑下来。"],["Get out of the way as soon as you come down.","滑下来后，尽快起来离开滑梯。"],["Don't climb up the slide. You might get hurt.","不要从滑梯上爬上去，以免受伤。"]]},{"n":43,"t":"玩跷跷板","sub":"游戏玩耍","lv":"初级","w":[["seesaw","跷跷板"],["side","边"],["face","面向"],["handle","把手"],["straight","笔直的"],["go up","上升"],["up and down","上上下下"],["get off","下来"]],"s":[["Do you want to play on the seesaw?","你想玩跷跷板吗？"],["Which side do you want to sit on?","你想坐哪一边呢？"],["I'll sit on the other side, facing you.","我将坐在另一边，面向你。"],["Hold onto the handle with both hands.","用双手握住把手。"],["Sit up straight. Don't lean too far back or forward.","坐直了。不要过度向后或向前倾斜。"],["Push gently on the ground with your feet to go up.","用脚轻轻地向地面施力以向上移动。"],["It rocks you up and down.","它会让你上下摇晃。"],["Can you get off by yourself?","你能自己下来吗？"]]},{"n":44,"t":"吹泡泡","sub":"游戏玩耍","lv":"初级","w":[["blow bubbles","吹泡泡"],["dip","浸，蘸"],["take out","取出"],["blow","吹"],["wave around","挥舞"],["float","漂浮"],["pop","使爆开"],["spill","洒出"]],"s":[["Let's go blow bubbles!","我们去吹泡泡吧！"],["Dip the wand in the bubble mixture.","将蘸棒浸入泡泡液中。"],["Take it out.","把它取出来。"],["Take a deep breath and blow gently.","深吸一口气然后轻轻地吹。"],["You can also wave the wand around.","你也可以挥动蘸棒。"],["The bubbles are floating away. Go catch them.","泡泡飘走了，去抓住它们吧。"],["Pop the bubble with your finger.","用你的手指戳破泡泡。"],["Be careful not to spill the bubble mixture.","小心不要弄洒泡泡液。"]]},{"n":45,"t":"吹气球","sub":"游戏玩耍","lv":"初级","w":[["balloon","气球"],["inflate","充气"],["pump","打气"],["stretch","拉伸"],["take a deep breath","深吸一口气"],["let out","放掉"],["tie","系、扎"],["pop","爆裂"]],"s":[["Let's blow up balloons.","我们来吹气球吧。"],["Inflate the balloon with a balloon pump.","用气球泵给气球充气。"],["Hold tight with your fingers and pump.","用手指捏紧并打气。"],["Stretch it a little bit.","稍微拉伸一下。"],["Take a deep breath and blow up the balloon with your mouth.","深吸一口气，用嘴吹气球。"],["The balloon was blown up too much. We'd better let some air out.","气球吹得太大了。我们最好放掉一些气。"],["Tie the balloon with a string.","用绳子把气球系起来。"],["Be careful not to pop the balloon.","小心不要把气球弄破了。"]]},{"n":46,"t":"玩沙子","sub":"游戏玩耍","lv":"中级","w":[["sandpit","沙坑"],["spin","旋转"],["crumble","松散"],["watering can","浇水壶"],["mold","模具"],["sandcastle","沙堡"],["dump truck","自卸卡车"],["rub","揉擦"]],"s":[["Let's go play in the sandpit.","我们去沙坑玩吧。"],["Scoop the sand and dump it into the funnel. Look, the wheels are spinning.","把沙子挖出来，倒入漏斗里。看，轮在转动。"],["The sand is too dry, it will crumble easily.","沙子太干了，很容易松散。"],["Let's fill the watering can with water and wet the sand.","我们给浇水壶灌水，然后弄湿沙子吧。"],["Fill the mold with wet sand, then flip it over and gently tap it to remove the mold.","用湿沙填满模具，然后翻过来，轻轻敲以去掉模具。"],["We can use the bucket to make a sandcastle.","我们用小桶做一个沙堡吧。"],["Let's move more sand here with the dump truck.","我们用自卸卡车运更多的沙子过来吧。"],["Don't rub your eyes with a sandy hand.","不要用沾满沙子的手揉眼睛。"]]},{"n":47,"t":"玩水枪","sub":"游戏玩耍","lv":"初级","w":[["water gun","水枪"],["suck up","抽取"],["shoot","射击"],["push in","推入"],["be careful","小心"],["aim","瞄准"],["stream","水流"],["water's edge","水边"]],"s":[["Put the tip of the water gun into the water.","将水枪枪头放入水中。"],["Pull the handle to suck it up.","拉动手柄将其吸水。"],["Let's see how far you can shoot.","我们看看你能射多远。"],["Push the handle in to shoot out the water.","把手柄往里推就可以把水射出来了。"],["Be careful not to shoot at others.","小心别喷到别人哦。"],["Let's aim at these bushes.","我们瞄准这些灌木丛吧。"],["Push harder to make the stream go farther.","用力推，射得更远。"],["Make sure you stay at a safe distance from the water's edge.","确保站在一个离水边安全距离的地方。"]]},{"n":48,"t":"石头剪刀布","sub":"游戏玩耍","lv":"初级","w":[["play","玩"],["crush","压碎"],["cut","剪"],["wrap","包，裹"],["at the same time","同时"],["draw","平局"],["change","改变"],["win","获胜"]],"s":[["Do you want to play rock, paper, scissors?","你想玩石头剪刀布吗？"],["You make a fist for rock like this. Rock crushes scissors.","像这样握紧拳头代表石头。石头压碎剪刀。"],["Put two fingers out, that's scissors. Scissors cut paper.","伸出两个手指就是剪刀。剪刀剪布。"],["Stretch out your hand as paper. Paper wraps rock.","将手伸展开表示布。布包住石头。"],["We should shoot at the same time.","我们要同时出拳。"],["If we both shoot the same gesture, it's draw.","如果我们出的一样，那就是平局。"],["You can't change after shooting.","出了之后就不能改变哦。"],["Let's see who wins two out of three.","我们看看谁能三局两胜吧。"]]},{"n":49,"t":"整理玩具","sub":"游戏玩耍","lv":"初级","w":[["all over","到处都是"],["trip","绊倒"],["clean up","收拾"],["pick up","捡起"],["bookshelf","书架"],["toy box","玩具箱"],["dust off","掸去灰尘"],["helper","帮手"]],"s":[["Your toys are all over the floor.","你的玩具满地都是。"],["You might trip and fall down.","你可能会被绊倒。"],["Let's clean them up.","我们来收拾一下吧。"],["Pick it up and put it where it belongs.","捡起来，放回它原本的位置。"],["Can you put the books on the bookshelf?","你能把书放到书架上吗？"],["Where should the cars go? They go to the toy box.","汽车应该放哪里呢？它们应该去玩具箱里。"],["The stuffed toy is a bit dusty. Dust it off.","这个毛绒玩具有点落灰了。掸去灰尘吧。"],["It's all clean now. You are such a good helper.","现在都收拾干净了。你真是个好帮手。"]]},{"n":50,"t":"换电池","sub":"游戏玩耍","lv":"中级","w":[["battery","电池"],["screwdriver","螺丝刀"],["triple A battery","7号电池"],["spring","弹簧"],["negative end","负极"],["slot","插槽"],["clockwise","顺时针"],["work","运转"]],"s":[["The toy is out of battery. Let's replace the battery.","玩具没电了。我们换个电池吧。"],["Use a screwdriver to unscrew the battery holder and turn it counterclockwise.","用螺丝刀逆时针旋转来打开电池仓。"],["We need two triple A batteries.","我们需要两节7号电池。"],["The flat side is the negative end. It goes against the spring.","电池的扁平一侧是负极。负极抵在弹簧上。"],["Place the negative end in first, then click the positive end in.","先把负极放进去，再把正极卡进去。"],["Make sure it fits perfectly in the slot.","确保电池在插槽中卡稳了。"],["Put the cover back on and tighten the screw clockwise.","把盖子盖上，顺时针拧紧螺丝。"],["Look, it's working now.","看，有电啦。"]]},{"n":51,"t":"做包子","sub":"我是小帮手","lv":"中级","w":[["dough","面团"],["knead","揉捏"],["double in size","两倍大"],["roll","滚动"],["rolling pin","擀面杖"],["filling","馅料"],["wrap","包裹"],["steamed bun","包子"]],"s":[["Mix flour, water and yeast together to make the dough.","将面粉，水和酵母混合制成面团。"],["Knead the dough until the surface is smooth.","将面团揉至表面光滑。"],["Let the dough rest until it rises to double in size.","让面团发酵至两倍大。"],["Roll the dough into a long strip and cut it into small pieces.","将面团擀成长条状，然后切成小块。"],["Roll it out into a round wrapper with a rolling pin.","用擀面杖将其擀成圆形面皮。"],["Add just the right amount of filling in the center.","在中间放上适量馅料。"],["Wrap the dough around the filling.","用面团包裹住馅料。"],["Now let's steam the steamed buns.","现在我们来蒸包子吧。"]]},{"n":52,"t":"包饺子","sub":"我是小帮手","lv":"中级","w":[["filling","馅料"],["wrapper","饺子皮"],["scoop","用勺舀"],["edge","边缘"],["pinch","捏"],["curvy","弯曲的"],["boiling water","沸水"],["float","漂浮"]],"s":[["Chop the vegetables and mix them with the minced meat, then add some seasonings to make the filling.","切碎蔬菜并与肉末混合，然后加入一些调料制成馅料。"],["Hold the wrapper in the palm.","把饺子皮放在掌心。"],["Scoop out some filling and put it in the center of the wrapper.","舀一勺馅料放在饺皮中间。"],["Wet the edge with water.","用水把边缘蘸湿。"],["Fold it over and pinch the edges tight.","把饺皮对折，然后紧紧捏住边缘。"],["Make the sides curvy.","把边缘捏出褶皱。"],["Put the dumplings into boiling water and stir them gently.","把饺子放入沸水中，然后轻轻搅拌。"],["When the dumplings are floating on the water, it means they are fully cooked.","当饺子浮在水面上时，就意味着煮熟了。"]]},{"n":53,"t":"烤饼干","sub":"我是小帮手","lv":"初级","w":[["cookie","饼干"],["butter","黄油"],["crack","打碎"],["sift","筛"],["roll out","擀平"],["cookie cutter","饼干模具"],["oven","烤箱"],["cool down","冷却"]],"s":[["Let's bake cookies.","我们来烤饼干吧。"],["First mix the butter and sugar.","首先将黄油和糖混合在一起。"],["Crack an egg into the bowl and stir it well.","打入一个鸡蛋，并搅拌均匀。"],["Sift in the flour and stir the mixture into a dough.","筛入面粉，将混合物搅拌成面团。"],["Roll out the dough evenly.","均匀地擀开面团。"],["Cut the dough out with the cookie cutters.","用饼干模具把面团切出来。"],["Bake in the preheated oven for about 20 minutes.","在预热好的烤箱中烤大约20分钟。"],["We can enjoy the cookies after they cool down!","等饼干冷却后，我们就可以享用啦！"]]},{"n":54,"t":"做松饼","sub":"我是小帮手","lv":"初级","w":[["recipe","食谱"],["flour","面粉"],["pour","倒"],["crack","打碎"],["whisk","打蛋器"],["pan","平底锅"],["spatula","锅铲"],["honey","蜂蜜"]],"s":[["Time to make pancakes. Let's take a look at the recipe.","做松饼啦，我们来看看配方。"],["First put some flour in the bowl.","先把面粉放进碗里。"],["Pour in the milk.","倒入牛奶。"],["Crack an egg into the bowl.","碗里打入一个鸡蛋。"],["Use the whisk to stir the mixture well.","用打蛋器将混合物搅拌均匀。"],["Pour the batter into the pan.","把面糊倒进锅里。"],["Flip the pancake with a spatula.","用锅铲给松饼翻个面。"],["Drizzle some honey over the pancakes.","在松饼上淋一些蜂蜜。"]]},{"n":55,"t":"烤吐司","sub":"我是小帮手","lv":"中级","w":[["toast","吐司"],["toaster","吐司机"],["slot","槽"],["starter","启动按钮"],["pop up","弹出"],["crunchy","松脆的"],["peanut butter","花生酱"],["flavor","口味"]],"s":[["Let me show you how to make a toast.","让我教你们如何烤吐司。"],["We need a slice of bread and a toaster.","我们需要一片面包和一个吐司机。"],["Put the bread into the slot of the toaster.","把面包放进吐司机的插槽里。"],["Press the starter. The light is on, it means the toaster is working.","按下启动按钮，灯亮了说明吐司机开始工作了。"],["Did you hear that? The bread just popped up.","你听见了吗？面包弹起来了，吐司烤好啦。"],["The toast tastes crunchy and crispy.","吐司吃起来酥脆可口。"],["You can spread some peanut butter or jam on the toast.","你可以在吐司上涂一些花生酱或者果酱。"],["What flavor do you prefer? Strawberry or blueberry?","你喜欢哪种口味？草莓的还是蓝莓的？"]]},{"n":56,"t":"煎鸡蛋","sub":"我是小帮手","lv":"初级","w":[["stove","炉子"],["gas","煤气"],["oil","油"],["crack","破裂"],["garbage can","垃圾桶"],["fry","油煎"],["spatula","锅铲"],["plate","盘子"]],"s":[["Put a frying pan on the stove.","把煎锅放在炉子上。"],["Turn on the gas.","打开煤气。"],["Pour some oil into the frying pan.","将油倒入煎锅中。"],["Crack an egg into the pan.","往锅里打一个鸡蛋。"],["Throw the shell into the garbage can.","将壳扔进垃圾桶。"],["The egg fries.","煎蛋。"],["Flip it over once with a spatula.","用锅铲翻个面。"],["Take the egg out of the pan and put it on a plate.","把鸡蛋从锅里盛出放在盘子里。"]]},{"n":57,"t":"剥鸡蛋","sub":"我是小帮手","lv":"初级","w":[["boiled egg","水煮蛋"],["tap","轻敲"],["roll","翻滚"],["cracked","破裂的"],["peel off","剥落"],["bit by bit","一点一点地"],["yolk","蛋黄"],["choke","噎住"]],"s":[["Would you like a boiled egg?","你想要吃水煮蛋吗？"],["Tap it on the table.","在桌子上敲一敲。"],["Roll the egg.","滚一滚。"],["Can you hear the shell is cracked?","你能听到外壳破裂的声音吗？"],["Let's start peeling off the shell.","让我们开始剥蛋壳吧。"],["The egg white is stuck to the shell. Peel it bit by bit.","蛋白粘在蛋壳上了，一点一点剥。"],["The white part is egg white and the yellow part is egg yolk.","白色部分是蛋白，黄色部分是蛋黄。"],["Take small bites or you might choke on it.","小口吃，否则可能会噎到哦。"]]},{"n":58,"t":"煮米饭","sub":"我是小帮手","lv":"中级","w":[["measure cup","量杯"],["inner pot","内锅"],["rinse","冲洗"],["add","添加"],["rice cooker","电饭煲"],["power cord","电源线"],["cooking mode","烹饪模式"],["switch","切换"]],"s":[["Use the measure cup to measure out one cup of rice.","用量杯量出一杯大米。"],["Pour the rice into the inner pot.","把米饭倒进内锅。"],["Rinse the rice with water and pour off the water to get rid of the dirt and husks.","用水冲洗大米，然后倒掉水以去除杂质和谷壳。"],["Add two cups of clean water into the pot.","向锅中加入两杯清水。"],["Dry the bottom of the pot and put it back into the rice cooker.","把锅底擦干，然后把它放回电饭煲里。"],["Close the lid and plug the power cord into the socket.","盖上盖子，把电源线插到插座上。"],["Choose the cooking mode.","选择烹饪模式。"],["When the rice is cooked, it will automatically switch to a keep-warm mode.","当米饭煮熟后，它会自动切换到保温模式。"]]},{"n":59,"t":"餐前准备","sub":"我是小帮手","lv":"初级","w":[["set the table","摆饭桌"],["count","数数"],["chopsticks","筷子"],["rice","米饭"],["rice cooker","电饭煲"],["steam","水蒸气"],["rice scoop","饭勺"],["dish","菜肴"]],"s":[["Can you help me set the table?","你能帮我摆饭桌吗？"],["First we need to count how many people will eat.","首先，我们需要数一下有几个人吃饭。"],["Bring the chopsticks and spoons to the table.","把筷子和匙子拿到餐桌上来。"],["Can you serve us some rice?","你能给我们盛些米饭吗？"],["Be careful when you open the rice cooker.","当你打开电饭煲时要小心点。"],["The steam is very hot.","水蒸气会很烫。"],["Use the rice scoop to scoop the rice.","用饭勺把米饭盛出来。"],["Please carry the dishes with both hands.","请用双手端着这些菜。"]]},{"n":60,"t":"餐桌礼仪","sub":"我是小帮手","lv":"初级","w":[["table","桌子"],["drum","击打"],["talk","说话"],["slurp","大声啜喝"],["picky","挑剔的"],["stand up","站起来"],["wipe","擦"],["lick","舔"]],"s":[["Wait until everyone is at the table.","等众人齐了再开动。"],["Don't drum on your bowl with chopsticks.","不要用筷子敲碗。"],["Don't talk with your mouthful.","不要边吃边说话。"],["Don't slurp the soup.","喝汤不要发出声响。"],["Don't be picky with your food. Eat more vegetables.","不要挑食，多吃点蔬菜。"],["Don't stand up to get the food that you can't reach. I'll help you with it.","不要站起来去拿你够不着的食物，我会帮你拿的。"],["Stop wiping with your hands or sleeves, use the napkin.","不要用手或者袖子擦拭，用餐巾纸。"],["Don't lick your fingers, go wash them.","别舔手指，去洗手吧。"]]},{"n":61,"t":"餐后收拾","sub":"我是小帮手","lv":"中级","w":[["clear up","收拾"],["leftovers","剩饭剩菜"],["lid","盖子"],["refrigerator","冰箱"],["scraps","食物残渣"],["stack up","叠放"],["garbage can","垃圾桶"],["push in","推进"]],"s":[["Can you help me clear up the table?","你能帮我收拾一下桌子吗？"],["Put the leftovers into containers.","把剩的食物放入容器里。"],["Remember to put the lid on tight.","记得把盖子盖紧。"],["Then put them into the refrigerator so that the food can stay fresh.","然后将它们放入冰箱，这样食物就能保持新鲜了。"],["Scrape the scraps from the plates into the garbage.","将盘子里的残渣刮到垃圾桶。"],["Stack up the dirty dishes and carry them to the sink.","把脏盘子摞起来放进水槽里。"],["Wipe the table clean and throw the scraps from the table into the garbage can.","把桌子擦干净，把桌上的碎屑扔进垃圾桶。"],["Push in the chairs.","把椅子推进去。"]]},{"n":62,"t":"洗碗","sub":"我是小帮手","lv":"初级","w":[["dish","碟，盘"],["sink","水槽"],["dish soap","洗洁精"],["sponge","海绵"],["edge","边缘"],["slippery","滑的"],["rinse","冲洗"],["dish rack","碗碟架"]],"s":[["do the dishes","洗碗"],["Fill the sink with water.","水槽里注入水。"],["Squeeze some dish soap onto the dirty dishes.","挤一些洗洁精到脏盘子上。"],["Use the sponge to scrub the dishes.","用海绵擦洗盘子。"],["Don't forget the edges and the outside.","别忘了擦洗边缘和外面面。"],["Be careful. The dishes are very slippery when they're soapy.","小心！盘子上有洗洁精的时候很滑。"],["Let's rinse the dishes with running water.","让我们用流水冲洗餐具。"],["Drain the dishes on the dish rack.","把盘子放在碗碟架上沥干。"]]},{"n":63,"t":"扫地拖地","sub":"我是小帮手","lv":"初级","w":[["sweep the floor","扫地"],["broom","扫帚"],["pile","一堆"],["dustpan","簸箕"],["trash can","垃圾桶"],["vacuum","吸尘器；用吸尘器打扫"],["mop","拖把，拖地"],["slip and fall","滑倒"]],"s":[["Look at the dirty floor. Let's sweep the floor.","看看这脏兮兮的地板，我们来扫地吧。"],["Take a broom.","拿一把扫帚。"],["Sweep all the dust and dirt into a small pile.","把所有的灰尘和垃圾扫成一小堆。"],["Then sweep them into the dustpan.","然后把它们扫进簸箕里。"],["Dump the dust and dirt into the trash can.","把灰尘和污垢倒入垃圾桶。"],["Vacuum the carpet.","用吸尘器清理地毯。"],["Now mop the floor with a mop.","现在用拖把拖地。"],["Watch out for the wet floor. Be careful not to slip and fall.","当心湿的地板。"]]},{"n":64,"t":"洗衣服","sub":"我是小帮手","lv":"中级","w":[["laundry basket","洗衣篮"],["do the laundry","洗衣服"],["pocket","口袋"],["sort","把…分类"],["washing machine","洗衣机"],["laundry detergent","洗衣液"],["adjust","调整"],["spin","甩干"]],"s":[["The laundry basket is full.","洗衣篮已经满了。"],["Let's do the laundry. Take the laundry out of the basket.","我们去洗衣服吧。把洗衣篮里的衣服拿出来。"],["Check the pockets of the pants and shirts, and take out anything you find in them.","检查裤子和衬衫的口袋，并取出其中发现的任何物品。"],["Sort the clothes by separating dark colors from light.","把衣服按深色和浅色分类。"],["Put the laundry into the washing machine.","把脏衣服放进洗衣机里。"],["Add some laundry detergent to the washing machine.","在洗衣机中加入一些洗衣液。"],["Adjust the settings on the machine and turn it on.","调整洗衣机上的设置并开启它。"],["The washing machine will wash, rinse and spin the laundry.","洗衣机将进行洗涤、漂洗和脱水操作。"]]},{"n":65,"t":"晾衣服","sub":"我是小帮手","lv":"中级","w":[["be done","完成"],["take out","取出"],["hang dry","晾干"],["hanger","衣架"],["shake out","抖开"],["drying rack","晾衣架"],["raise","提起"],["clip hanger","夹子衣架"]],"s":[["The laundry is done.","衣服洗好了。"],["Can you help mommy take the laundry out of the washing machine?","你能帮助妈妈把衣服从洗衣机里拿出来吗？"],["Let's hang dry the clothes.","我们把衣服晾干吧。"],["Can you pass me the hanger?","你可以把衣架递给我吗？"],["Shake out the clothes and hang them on the hangers.","把衣服抖开，挂在衣架上。"],["Lower the drying rack and put the hanger on it.","把晾衣架放下来，然后把衣架挂上去。"],["Raise the drying rack and make sure the clothes don't hit the ground.","把晾衣架升上去，确保衣服不会碰到地上。"],["We can use the clip hanger to clip on socks and underwear.","我们可以用夹子衣架把袜子和内衣夹起来。"]]},{"n":66,"t":"种花","sub":"我是小帮手","lv":"初级","w":[["flower","花"],["pot","花盆"],["dig","挖"],["seed","种子"],["backfill","回填"],["water","浇水"],["germinate","发芽"],["take time","需要时间"]],"s":[["Let's plant some flowers.","我们来种些花吧。"],["First put the soil in the pot.","首先把土壤放入花盆中。"],["Dig small holes in the soil.","在土壤中挖一些小洞。"],["Sow the seeds loosely and evenly.","把种子均匀地撒开。"],["Backfill the hole with the soil.","用土壤回填满洞洞。"],["Water the seeds regularly to keep the soil moist.","定期浇水保持土壤湿润。"],["Seeds will germinate, grow into buds, and then bloom.","种子会发芽，长出花苞，然后开花。"],["It takes time, so you need to be patient.","这需要时间，所以你得有耐心。"]]},{"n":67,"t":"垃圾分类","sub":"我是小帮手","lv":"中级","w":[["waste sorting","垃圾分类"],["hazardous waste","有害垃圾"],["recyclable","可回收垃圾"],["food waste","厨余垃圾"],["residual waste","其他垃圾"],["dispose","处理"],["reprocess","再加工"],["transform","转换"]],"s":[["Waste sorting is good for the environment and helps save resources.","垃圾分类有利于环境保护，并有助于节约资源。"],["Hazardous waste includes chemicals, batteries, etc.","有害垃圾包括化学制品、电池等。"],["Recyclable waste mainly includes paper, plastic, etc.","可回收垃圾主要包括废纸、塑料等。"],["Food waste mainly consists of peels, leftover food, etc.","厨余垃圾主要包括果皮、剩菜剩饭。"],["Tissues and dust belong to residual waste.","纸巾和尘土属于其他垃圾。"],["Hazardous waste must be disposed of properly to minimize the impact on the environment.","有害垃圾必须妥善处理，以尽量减少对环境的影响。"],["Recyclable waste can be reprocessed into new products, to reduce our need for natural resources.","可回收垃圾能被再加工成新产品，以减少我们对自然资源的需求。"],["Food waste can be transformed into things like fertilizer or biogas to decrease the need for landfills and incineration.","厨余垃圾可以转化为肥料或沼气等物质，以减少对垃圾填埋场和焚烧的需求。"]]},{"n":68,"t":"取快递","sub":"我是小帮手","lv":"中级","w":[["package","包裹"],["package station","快递站"],["pickup code","取件码"],["bar code","条形码"],["package locker","快递柜"],["QR code","二维码"],["pop open","弹开"],["shut","关闭"]],"s":[["Let's go pick up the package.","我们去取快递吧。"],["This is the package station.","这是快递站。"],["There are so many shelves. We need to find the shelf with our pickup code on it.","这里有很多货架。我们得找到贴有我们取件码的货架。"],["Scan the bar code to get our package.","扫描条形码来取我们的包裹。"],["Sometimes the packages are delivered into the package locker.","有时候包裹会被放入快递柜。"],["We need to enter the pickup code or scan the QR code.","我们需要输入取件码或扫描二维码。"],["Then the door will pop open.","然后门会自动打开。"],["Let's take out the package. Don't forget to shut the door.","让我们把包裹拿出来。别忘了关门。"]]},{"n":69,"t":"上下楼梯","sub":"出行场景","lv":"初级","w":[["stair","楼梯"],["handrail","扶手"],["skip","跳过"],["landing","楼梯平台"],["steep","陡峭的"],["miss a step","踏空台阶"],["jump down","跳下"],["goof around","胡闹"]],"s":[["Let's take the stairs.","我们走楼梯吧。"],["Hold the handrail or mommy's hand.","握住扶手或者妈妈的手。"],["Don't skip steps, one step at a time.","不要连阶走，一步一步来。"],["This is the landing. We can have a rest here.","这里是楼梯平台，我们可以在这里休息一下。"],["The stairs are a little bit steep. Take it slow, no rush.","楼梯有点陡。慢慢来，不要着急。"],["Keep your eyes on the stairs. Don't miss a step.","眼睛看楼梯，别踩空啦。"],["Don't jump down the stairs. It's dangerous.","不要跳下楼梯，这很危险。"],["Don't goof around on the steps. You might get hurt.","不可以在楼梯上胡闹；你会受伤的。"]]},{"n":70,"t":"乘电梯","sub":"出行场景","lv":"中级","w":[["elevator","电梯"],["press","按"],["hold the door","把门开着"],["door close button","关门按钮"],["get off","离开"],["enter","进入"],["lean","倚靠"],["emergency button","紧急按钮"]],"s":[["Let's take the elevator.","我们乘电梯吧。"],["Press the up/down button and wait for it.","按下向上/向下按钮，然后等待电梯。"],["Let's get in the elevator. I'm holding the door for you.","我们进电梯吧，我帮你按着门。"],["Press the right number, then press the door close button.","按下正确的数字按钮，然后关闭电梯门。"],["Make sure the floor is correct before getting off the elevator.","下电梯前先确认楼层是否正确。"],["Let people exit before you enter.","先下后上。"],["Don't jump or lean against the doors in the elevator.","电梯里不要跳跃或倚靠门。"],["We can only press the emergency button when we are stuck in the elevator.","我们只有在被困在电梯中时才能按紧急按钮。"]]},{"n":71,"t":"乘扶梯","sub":"出行场景","lv":"中级","w":[["escalator","自动扶梯"],["step","台阶，迈步"],["avoid","避开"],["handrail","扶手"],["stand still","站着不动"],["right","右边"],["get off","离开"],["in reverse","相反"]],"s":[["Let's take the escalator to go upstairs / downstairs.","我们乘自动扶梯上楼/下楼吧。"],["We have to wait for a step to come, then step onto it.","我们要等一个台阶上来，然后迈上去。"],["Watch your step, and avoid the yellow line.","注意脚下，避开黄线。"],["Hold onto the handrail so we can stay steady.","抓住扶手，这样我们就能保持稳了。"],["Stand still. Don't jump or sit on it.","站稳了，不要跳或者坐在上面。"],["Stand on the right so that people can pass by on the left.","靠右站，这样人们就可以从左边通过了。"],["We're about to get off the escalator. Take a big step.","我们快要下扶梯了，大步跨过去。"],["Don't take the escalator in reverse.","不要逆向乘坐自动扶梯。"]]},{"n":72,"t":"散步","sub":"出行场景","lv":"中级","w":[["go for a walk","散步"],["backwards","向后"],["curb","马路牙子"],["e-bike","电瓶车"],["side","边，侧"],["manhole cover","井盖"],["inside","内侧"],["piggyback ride","背驮"]],"s":[["Let's go for a walk and get some fresh air.","我们出去散散步，呼吸一下新鲜空气吧。"],["Don't walk backwards, turn around.","别向后倒着走，转过身来。"],["Hold my hand and then you can walk on the curb.","握住我的手，然后你可以在马路牙子上。"],["Watch out for the e-bikes passing by.","小心来往的电瓶车。"],["Keep to the side. Don't block the road.","靠边走，不要挡路。"],["Don't step on the manhole covers on purpose as they might not be closed properly.","请不要故意踩井盖，因为它们可能没有完全盖好。"],["Honey, walk on the inside, and I'll be on the outside to keep you safe from the traffic.","宝贝，走内侧的路，我在外侧保护你免受车辆的伤害。"],["Do you want a piggyback ride?","你想骑在我的背上吗？"]]},{"n":73,"t":"露营","sub":"出行场景","lv":"初级","w":[["folding wagon","露营车"],["go camping","去露营"],["tent","帐篷"],["peg","地钉"],["hammock","吊床"],["air mattress","充气床"],["sleeping bag","睡袋"],["take a nap","小睡一会儿"]],"s":[["Put all the things we need into a folding wagon.","把我们需要的东西都装进露营车。"],["Let's go camping at a campsite.","我们去营地露营吧。"],["First we need to set up the tent.","我们需要先搭帐篷。"],["Hammer the pegs into the ground.","把地钉锤到地里去。"],["Let's sling a hammock between the trees.","我们在树间搭个吊床吧。"],["Use the pump to blow up the air mattress.","用充气泵给充气床充气。"],["Let's put the sleeping bags inside the tent.","让我们把睡袋放进帐篷里。"],["Now take a nap in the cozy tent.","现在在舒服的帐篷里小睡一会儿吧。"]]},{"n":74,"t":"野餐","sub":"出行场景","lv":"中级","w":[["picnic","野餐"],["picnic mat","野餐垫"],["spread out","铺开"],["corner","角落"],["shake out","抖开"],["take off","脱掉"],["lay out","摆开"],["clean up","收拾"]],"s":[["Let's go on a picnic.","我们去野餐吧。"],["Let's spread the picnic mat in the shade of the tree.","我们把野餐垫铺在树下吧。"],["Help me spread out the mat, please.","请帮我把垫子铺开吧。"],["Hold on to those two corners.","抓紧那两个角落。"],["Shake it out and set it on the ground gently.","抖一抖，把它轻轻放在地上。"],["Take off your shoes and sit wherever on the picnic mat.","脱下鞋子，在野餐垫上随便坐。"],["Let's lay out all the food. Clean your hands before eating.","我们把所有的食物都摆出来。吃饭前先洗手哦。"],["Time to go home. Let's clean up. Don't leave any trash behind.","该回家了。让我们收拾一下，不要留下任何垃圾。"]]},{"n":75,"t":"超市购物","sub":"出行场景","lv":"中级","w":[["supermarket","超市"],["shopping cart","购物车"],["free sample","试吃品"],["on sale","特价销售"],["expiration date","保质期"],["shopping list","购物清单"],["checkout counter","收银台"],["reusable","可重复使用的"]],"s":[["Let's go to the supermarket and do some shopping.","我们去超市购物吧。"],["Get a shopping cart.","推一辆购物车。"],["Here's a free sample. Give it a try.","尝尝这个试吃品吧。"],["Look at the price tag, this is on sale. It's a great deal.","看看价格标签，这是打折商品，很划算哦。"],["We need to check the production and expiration dates.","我们需要看一下生产日期和保质期。"],["Check the shopping list to see if we have everything we need.","看看购物清单，确认一下是否已经买齐了所有东西。"],["Let's go to the checkout counter and wait in line.","我们去收银台排队吧。"],["We can use reusable shopping bags to be more environmentally friendly.","我们可以使用可重复使用的购物袋来更加环保。"]]},{"n":76,"t":"公园喂鱼","sub":"出行场景","lv":"初级","w":[["park","公园"],["tear up","撕碎"],["toss","扔"],["swarm","一窝蜂"],["farther","更远的"],["trash","垃圾"],["pond","池塘"],["sign","标志"]],"s":[["Let's take the leftover bread to the park and feed the fish.","我们把剩的面包带到公园去喂鱼吧。"],["Tear up the bread into small pieces.","把面包撕成小块。"],["Let's toss the bread into the water.","我们把面包扔进水里吧。"],["Look, the fish are swarming the bread.","看，鱼儿都围着面包游过来了。"],["Throw a little farther.","再扔远一点吧。"],["Don't throw the trash into the water. If the fish eat it, they may get sick.","不要把垃圾扔进水里。如果鱼吃了，它们可能会生病。"],["Keep away from the edge of the pond.","请远离池塘边缘。"],["This sign says no fishing.","此标志表示禁止钓鱼。"]]},{"n":77,"t":"看电影","sub":"出行场景","lv":"中级","w":[["cinema","电影院"],["ticket","票"],["popcorn","爆米花"],["stub","票根"],["seat","座位"],["3D glasses","3D眼镜"],["keep quiet","保持安静"],["over","结束"]],"s":[["Let's go to the cinema to see a movie.","我们去电影院看电影吧。"],["Scan the QR code to get the tickets on the ticket machine.","扫描二维码就可以在售票机上取票了。"],["Would you like some popcorn and drinks?","你想要爆米花和饮料吗？"],["The ticket-taker will tear our tickets and return the stubs to us.","检票员会撕掉我们的票，并将票根还给我们。"],["The movie is in theater 6. Our seats are in Row 6, Seats 7, 8, and 9.","电影在6号厅放映。我们的座位在6排，7、8、9座。"],["It's a 3D movie. You have to put on the 3D glasses.","这是3D电影。你得带上3D眼镜。"],["It's starting now. Sit still and keep quiet.","电影开始了。坐好，保持安静哦。"],["The movie is over. Don't forget to pick up our trash.","电影结束了。别忘了清理我们的垃圾。"]]},{"n":78,"t":"拍照片","sub":"出行场景","lv":"初级","w":[["take photos","拍照片"],["step back","后退"],["peace sign","剪刀手"],["pose","姿势"],["candid shot","抓拍"],["blurry","模糊的"],["zoom in","放大"],["selfie","自拍照"]],"s":[["Let me take photos of you.","我来给你拍照片吧。"],["Step back a little. All right. Come forward a little.","稍微往后退一点。好了，再往前走一点。"],["Make a peace sign. Smile and say cheese.","比个剪刀手。笑一笑，说茄子。"],["Now let's change the pose.","现在让我们换个姿势吧。"],["Just act natural and I'll take a candid shot.","随意点，我来抓拍。"],["This photo was blurry, let's take another one.","这张照片很模糊，我们再拍一张吧。"],["Let me zoom in and get a better shot.","让我放大镜头，拍张更清晰的照片。"],["Let's take a selfie. Switch to the front facing camera.","我们来拍自拍照吧。切换到前置摄像头。"]]},{"n":79,"t":"过马路","sub":"出行场景","lv":"中级","w":[["cross the road","过马路"],["crosswalk","人行横道"],["crosswalk signal","人行横道信号灯"],["wait","等待"],["left and right","左右"],["hold one's hand","拉住…的手"],["stop","停止"],["jaywalk","乱穿马路"]],"s":[["Now we need to cross the road.","现在我们需要过马路。"],["Always remember to cross the road at the crosswalk.","始终记得在人行横道上过马路。"],["Pay attention to the crosswalk signal.","请注意人行横道信号灯。"],["It's red light now. Wait until the light turns green.","现在是红灯。请等到绿灯亮起。"],["We need to look left and right to make sure no traffic is coming.","我们需要左右看看，确保没有车辆驶来。"],["Hold mommy's hand tight until we reach the other side of the road.","紧紧牵着妈妈的手，直到我们走到路的另一边。"],["Keep going, don't stop in the middle.","继续前进，不要停在路中间。"],["Do not jaywalk. It's dangerous.","不要乱穿马路。这很危险。"]]},{"n":80,"t":"坐车出行","sub":"出行场景","lv":"中级","w":[["unlock","解锁"],["car seat","安全座椅"],["seat belt","安全带"],["hit the road","出发"],["lower","使…降下"],["door handle","门把手"],["stick","伸出"],["gas station","加油站"]],"s":[["Unlock the car and pull open the door.","解锁汽车，拉开车门。"],["Get in the car and sit in your car seat.","上车，坐在安全座椅上。"],["Let me help you fasten your seat belt.","让我来帮你系上安全带。"],["All set. Let's hit the road.","一切准备就绪，我们出发吧。"],["Lower the window to get in some fresh air.","把窗户放下来透透气。"],["Don't play with the door handle.","不要玩门把手。"],["Never stick your head or hands out of the window.","不要把头或者手伸出窗外。"],["We are running out of gas. Let's stop by a gas station to fill up.","车子快没油了，我们去加油站加油吧。"]]},{"n":81,"t":"乘公交","sub":"出行场景","lv":"中级","w":[["bus stop","公交车站"],["bench","长椅"],["in line","排队"],["swipe the card","刷卡"],["priority seat","优先座位"],["emergency hammer","逃生锤"],["back door","后门"],["handle","把手"]],"s":[["Let's take the bus at the bus stop.","我们去公交车站乘公交吧。"],["We can sit on the bench to wait for the bus.","我们可以坐在公交车站的长椅上等公交车。"],["Look. No. 6 bus is coming. Let's get on the bus in line.","看，6路公交车来了。我们排队上车吧。"],["Swipe the card or drop coins into the fare box.","刷卡或把硬币投入收费箱。"],["The priority seats are for people in need, like elderly people or pregnant women.","优先座位是留给有需要的人的，比如老年人或孕妇。"],["The emergency hammer is for breaking through the window in an emergency.","逃生锤是用于紧急情况下砸破窗户的。"],["We are almost to the stop. Let's move towards the back door to get off.","快到站了。我们到后门准备下车。"],["Hold on to the handle and press the stop button to ring the stop signal.","请抓住把手并按下停车按钮，发出下车信号。"]]},{"n":82,"t":"乘地铁","sub":"出行场景","lv":"中级","w":[["subway","地铁"],["security check","安检"],["scan","扫描"],["metro map","地铁线路图"],["safety line","安全线"],["gap","缝隙"],["seat","座位"],["exit","出口"]],"s":[["Let's take the subway to the museum.","我们坐地铁去博物馆吧。"],["Let's go through the security check and place our belongings on the conveyor belt.","让我们通过安检，并将我们的物品放在传送带上。"],["We can swipe our card or scan the QR code to pass the barrier.","我们可以刷卡或扫描二维码过闸机。"],["Check the metro map and make sure we are on the right platform.","查看地图，确保在正确的站台上。"],["Stay behind the safety line and wait for the subway to arrive.","站在黄线后等待地铁到来。"],["Be careful of the gap between the subway and the platform.","小心地铁站台之间的缝隙。"],["Find a seat or hold onto the pole and stand still.","找个座位或者握紧扶杆站稳了。"],["This is our stop, let's get off and find the exit to the ground.","到站了，让我们下车然后找到通往地面的出口吧。"]]},{"n":83,"t":"乘出租车","sub":"出行场景","lv":"初级","w":[["taxi","出租车"],["hail","招呼"],["pull over","靠边停车"],["back seat","后座"],["meter","计价器"],["navigation","导航"],["drop off","下车"],["fare","费用"]],"s":[["Let's take a taxi to the supermarket.","我们打的去超市吧。"],["Hail the taxi by waving our hands like this.","我们可以像这样挥手来招呼出租车。"],["The taxi will pull over to us.","出租车会靠边停在我们旁边。"],["Get into the back seat.","上后座吧。"],["Tell the driver where we want to go, and he'll start the meter.","告诉司机我们要去哪里，他就会开始计价。"],["Follow the navigation.","跟着导航开。"],["Ask the driver to drop us off here.","请司机在这里让我们下车。"],["Check the meter and pay the fare.","查看计价器并支付车费。"]]},{"n":84,"t":"打车","sub":"出行场景","lv":"初级","w":[["ride-hailing app","打车软件"],["departure location","出发地点"],["destination","目的地"],["driver","司机"],["map","地图"],["arrive","到达"],["license plate number","车牌号"],["cellphone","手机"]],"s":[["Let's use the ride-hailing app to hail a cab.","我们用打车软件打个车吧。"],["Check our departure location.","确认我们的出发地点。"],["Then enter our destination.","然后输入我们的目的地。"],["Now we have to wait for a driver to accept.","现在我们要等司机接单。"],["If a driver takes the order, it'll show up on the map.","如果有司机接单，地图上会显示。"],["It'll arrive in five minutes.","车将在5分钟后到达。"],["Check the DiDi's license plate number before hopping in.","上车前确认滴滴车的牌号。"],["We've arrived. Let's pay the fare with our cellphone.","我们到了，在手机上支付车费。"]]},{"n":85,"t":"收拾行李","sub":"出行场景","lv":"中级","w":[["go on a trip","去旅行"],["pack up","收拾行李"],["list","列清单"],["fold","折叠"],["roll up","卷起"],["coil up","盘绕"],["what else","还有什么其他的"],["souvenir","纪念品"]],"s":[["We are going on a trip tomorrow.","我们明天要去旅行了。"],["Let's pack up for the trip now.","现在我们收拾行李吧。"],["Let's list all the necessary things for the trip.","我们把旅行所需的所有东西都列出来吧。"],["Fold your clothes to make them smaller and put them into the suitcase.","把衣服折叠小一点放进行李箱。"],["Roll the pants up to make them smaller and prevent wrinkles.","把裤子卷起来，使它们变小，还能防止起皱。"],["Coil the charger up so it won't get tangled.","把充电器盘绕起来，这样就不会打结了。"],["What else do you want? How about packing some books and toys?","你还需要什么？带些书和玩具怎么样？"],["Leave some extra room so we can take some souvenirs home.","留点空间出来，这样我们可以带些纪念品回家。"]]},{"n":86,"t":"乘飞机","sub":"出行场景","lv":"中级","w":[["check-in counter","值机柜台"],["security check","安检"],["gate","登机口"],["jet bridge","登机桥"],["overhead compartment","行李架"],["seat belt","安全带"],["take off","起飞"],["baggage claim","行李提取"]],"s":[["Let's check in our baggage and get the boarding passes at the check-in counter.","我们在值机台办理托运行李和领取登机牌。"],["We are going through the security check now.","现在我们要过安检了。"],["Find our gate and wait for boarding.","找到我们的登机口，等待登机。"],["This is the jet bridge, it takes us directly to the plane.","这是登机桥，它可以直接带我们到飞机上。"],["Put the carry-on in the overhead compartment.","把随身行李放在行李架上。"],["Please fasten your seat belt and remain seated during takeoff and landing.","请系好安全带，在起飞和降落时坐在座位上。"],["The plane is starting to taxi, and we'll be taking off soon.","飞机开始滑行了，我们马上就要起飞了。"],["We need to go to the baggage claim to get our baggage.","我们要去行李提取处拿我们的行李箱。"]]},{"n":87,"t":"乘高铁","sub":"出行场景","lv":"中级","w":[["high-speed train","高铁"],["security check","安检"],["gate","闸门"],["platform","站台"],["window seat","靠窗座位"],["luggage rack","行李架"],["adjust","调整"],["get off","下车"]],"s":[["Let's go to the railway station to take the high-speed train.","我们去火车站乘高铁吧。"],["Go through security check, which includes a baggage scan and body screening.","过安检，包括行李扫描和身体检查。"],["Swipe the ID card to go through the gate.","刷身份证过闸门。"],["Wait at the right platform for our train.","在正确的站台等待我们的火车。"],["Board the train and find your seat. It's a window seat.","登上火车，找到你的座位。是个靠窗座位。"],["Put our bags on the luggage rack.","把行李放在行李架上。"],["You can adjust the seat by pressing this button.","你可以按这个按钮来调整座椅。"],["This is our stop, let's get off with our belongings.","我们到站了，带着行李下车吧。"]]},{"n":88,"t":"住酒店","sub":"出行场景","lv":"中级","w":[["hotel","酒店"],["key card","房卡"],["reservation","预定"],["ID","身份证件"],["elevator","电梯"],["swipe","刷（卡）"],["insert","插入"],["deposit","定金"]],"s":[["Here we are at the hotel.","我们到酒店了。"],["First we need to check in to get our key card.","首先我们要办理入住拿房卡。"],["I have a reservation under the name of Jojo.","我有一个以Jojo名字定的房间。"],["We need to confirm the information and show our ID.","我们需要确认信息并出示身份证。"],["Our room number is 1002. Let's take the elevator to the 10th floor.","我们的房间号是1002，乘电梯去10楼吧。"],["Swipe the key card to unlock the door.","刷房卡打开房门。"],["Let's get into the room and insert the card into the slot to get power.","我们进房间后，把房卡插到插槽取电。"],["Time to check out. I'll hand the key card to the front desk worker and get the deposit back.","到退房时间了。我要把房卡交给前台工作人员，然后拿回押金。"]]},{"n":89,"t":"生日","sub":"节日","lv":"中级","w":[["birthday","生日"],["birthday hat","生日帽"],["candle","蜡烛"],["make a wish","许愿"],["blow out","吹灭"],["cut","切"],["wait","等待"],["gift","礼物"]],"s":[["Happy birthday, sweetie! You are turning 5 years old today.","生日快乐，宝贝！今天你5岁啦！"],["Put on the birthday hat. Wow, you look like a little prince / princess.","戴上生日帽。哇，你看起来像一个小王子/公主。"],["Let's light the candles with a lighter and sing the birthday song.","用打火机点亮蜡烛，然后唱生日歌吧。"],["Now close your eyes and make a wish.","现在闭上眼睛许愿吧。"],["Time to blow out the candles. Blow hard.","吹灭蜡烛吧。用力吹。"],["Take out the candles and then cut the cake.","让我们把蜡烛拿出来，然后切蛋糕吧。"],["I can't wait. Let's dig in!","我等不及了，开动吧！"],["Here's the gift for you. Open it and have a look.","这是给你的生日礼物。打开看看吧。"]]},{"n":90,"t":"劳动节","sub":"节日","lv":"初级","w":[["firefighter","消防员"],["farmer","农民"],["traffic police","交警"],["sanitation worker","环卫工人"],["doctor","医生"],["security guard","保安"],["teacher","老师"],["delivery person","快递员"]],"s":[["The firefighters can put out the fire and rescue people.","消防员会灭火并营救人们。"],["Farmers grow vegetables and fruits on the farm.","农民在农场里种植蔬菜和水果。"],["The traffic police direct the vehicles to keep the traffic orderly.","交警指挥车辆使交通井然有序。"],["The sanitation workers make the city neat and clean.","环卫工人让城市整洁干净。"],["A doctor's job is to treat people who are ill.","医生的工作是治疗病人。"],["Security guards patrol the community.","保安在小区里巡逻。"],["Teachers teach students knowledge.","老师教学生知识。"],["The delivery person delivers packages to us.","快递员把包裹送给我们。"]]},{"n":91,"t":"母亲节","sub":"节日","lv":"中级","w":[["Mother's Day","母亲节"],["feed","喂养"],["hug","拥抱"],["play with...","与......一起玩"],["read","朗读"],["help","帮助"],["teach","教"],["best","最好的"]],"s":[["Mother's Day is on the second Sunday in May.","五月的第二个星期天是母亲节。"],["I love my mummy because she feeds me.","我爱妈妈因为她喂我。"],["I love my mummy because she hugs me goodnight.","我爱妈妈因为她抱着我入睡。"],["I love my mummy because she plays with me.","我爱妈妈因为她陪我玩。"],["I love my mummy because she reads to me.","我爱妈妈因为她给我讲故事。"],["I love my mummy because she always helps me.","我爱妈妈因为她总能帮助我。"],["I love my mummy because she teaches me.","我爱妈妈因为她教我不会的事情。"],["I love my mummy because she is the best mummy in the world.","我爱妈妈因为她是全世界最好的妈妈。"]]},{"n":92,"t":"父亲节","sub":"节日","lv":"中级","w":[["Father's Day","父亲节"],["appreciate","感恩"],["mountain","山"],["safe","安全的"],["laugh","笑"],["by one's side","在身边"],["superhero","超级英雄"],["hug","拥抱"]],"s":[["Father's Day is held on the third Sunday in June.","父亲节在六月的第三个星期日。"],["It's a day to appreciate dads.","这是感恩父亲的日子。"],["Father's love is as vast and high as a mountain.","父爱如山般高远。"],["I love my dad because he keeps me safe and cozy.","我爱我的爸爸因为他让我感觉安全舒适。"],["I love my dad because he makes me laugh when I am sad.","我爱我爸爸因为当我难过的时候他总能逗我笑。"],["With dad by my side, there's nothing we can't do.","只要爸爸在我们身边，我们就可以无所不能。"],["You are my superhero. Happy Father's Day!","你是我的超级英雄。父亲节快乐！"],["There are many ways to celebrate, such as giving gifts and giving dad a hug.","有很多种庆祝方式，如送礼物，给爸爸一个拥抱。"]]},{"n":93,"t":"儿童节","sub":"节日","lv":"中级","w":[["Children's Day","儿童节"],["improve","改善"],["have fun","玩得开心"],["performance","表演"],["decorate","装饰"],["favorite","最喜欢的"],["treat","美食"],["gift","礼物"]],"s":[["The international Children's Day is on June 1st every year.","国际儿童节在每年的6月1日。"],["The establishment of this festival is aimed at improving the lives of children.","这个节日的设立旨在改善儿童的生活。"],["It is a day for kids to have fun and be happy!","这是孩子们玩乐和快乐的日子！"],["The school organizes various activities like performance and games to celebrate.","学校组织各种表演和游戏来庆祝。"],["We also decorate our classrooms with colourful balloons and streamers.","我们还用五颜六色的气球和彩带装饰教室。"],["Children wear their favorite clothes.","孩子们穿上他们最喜欢的衣服。"],["Kids can eat lots of delicious treats.","孩子可以吃很多好吃的。"],["They can also receive many gifts.","他们也可以收到许多礼物。"]]},{"n":94,"t":"端午节","sub":"节日","lv":"中级","w":[["Dragon Boat Festival","端午节"],["commemorate","纪念"],["zongzi","粽子"],["dragon boat","赛龙舟"],["egg","鸡蛋"],["sachet","香囊"],["realgar wine","雄黄酒"],["mugwort leaves","艾叶"]],"s":[["The Dragon Boat Festival falls on the fifth day of the fifth lunar month.","端午节在农历五月初五这一天。"],["It commemorates the patriotic poet Qu Yuan.","它是为纪念爱国主义诗人屈原。"],["Zongzi is the most important food eaten on the Dragon Boat Festival.","粽子是端午节最重要的食物。"],["Dragon boat racing is an important folk activity that people engage in during the Dragon Boat Festival.","赛龙舟是端午节人们参与的一项重要民俗活动。"],["Many places also hold the egg balancing competition at noon.","很多地方也会在中午举行鸡蛋竖立比赛。"],["Children wear scented sachets to ward off evil.","孩子们会佩戴香囊驱邪。"],["People drink realgar wine to drive evil things away and pray for good health.","人们喝雄黄酒驱邪，祈愿健康。"],["People put mugwort leaves and calamus on doors or windows to repel insects from the house.","人们将艾叶和菖蒲挂于门前驱除虫。"]]},{"n":95,"t":"裹粽子","sub":"节日","lv":"中级","w":[["soak","浸泡"],["filling","馅料"],["cone","圆锥"],["press","按压"],["fold over","翻折"],["tie","系、绑"],["boil","煮"],["remove","去除"]],"s":[["Soak the glutinous rice and reed leaves overnight with water.","将糯米和芦苇叶浸泡过夜。"],["Prepare the sweet or savory fillings you like.","准备你喜欢的甜口或咸口的馅料。"],["Put two leaves together and fold them around to form a cone.","把两片叶子合在一起，然后把它们卷起来形成一个圆锥。"],["Add the glutinous rice and fillings to the cone, then press it firmly.","加入糯米和馅料并压紧实。"],["Fold over the leaves to close the top completely and fold the extra leaves to one side.","把叶子翻折过来完全盖住顶部，并把多余的叶子折到一边。"],["Tie it up with a string.","用线把它捆起来。"],["Boil the zongzi in hot water.","把粽子放在热水里煮。"],["Untie the string and remove the leaves. Now we can enjoy it.","解开绳子，去掉叶子。现在我们可以享用了。"]]},{"n":96,"t":"中秋节","sub":"节日","lv":"中级","w":[["Mid-Autumn Festival","中秋节"],["harvest","丰收"],["get together","相聚"],["mooncake","月饼"],["full moon","满月"],["lantern","灯笼"],["osmanthus wine","桂花酒"],["Chang'e","嫦娥"]],"s":[["Mid-Autumn Festival is on the 15th day of the 8th lunar month.","中秋节在农历八月十五日。"],["It is a traditional Chinese holiday which symbolizes reunion and harvest.","中秋节是中国传统节日，象征着团圆和丰收。"],["Families will get together and have a big dinner on that day.","在那天，家人们会聚在一起共进一顿丰盛的晚餐。"],["People eat a moon-shaped pastry called mooncake.","人们吃一种月亮形状的月饼糕点，叫做月饼。"],["We can appreciate a super bright and round full moon on the night of the Mid-Autumn Festival.","我们可以在中秋节的夜晚欣赏到一轮超级明亮圆润的满月。"],["People often light lanterns and enjoy outdoor activities.","人们经常点亮灯笼，享受户外活动。"],["There is also the custom of drinking osmanthus wine during the Mid-Autumn Festival.","中秋节还有喝桂花酒的习俗。"],["Adults will tell kids the story of Chang'e.","大人们会给孩子讲述嫦娥的故事。"]]},{"n":97,"t":"赏月","sub":"节日","lv":"中级","w":[["moon","月亮"],["sun","太阳"],["phases of the moon","月相"],["new moon","新月"],["full moon","满月"],["earth","地球"],["Jade Rabbit","玉兔"],["poem","诗"]],"s":[["Look at the bright full moon in the night sky. The moon doesn't emit light itself.","看看夜空中明亮的满月。月亮本身不会发光。"],["The moon light we see is actually the sun's light reflected off the lunar surface.","我们看到的月光实际上是阳光在月球表面反射形成的。"],["The phases of the moon are a visual phenomenon caused by the changing angle of sunlight on the moon's surface.","月相是由于阳光照射在月球表面的角度变化引起的视觉现象。"],["It begins with a new moon and gradually increases to a full moon.","月亮从新月开始逐渐增大到满月。"],["As the light begins to decrease on its surface, it starts its return journey from full moon to the invisible new moon.","当月球表面的光线开始减弱时，月亮开始从满月回到看不见的新月。"],["The moon revolves around the earth and finishes its journey in about 29.5 days.","月亮围绕地球旋转，大约29.5天完成一次公转。"],["People believe that Jade Rabbit lives on the moon. Can you spot it?","人们相信月亮上住着玉兔。你能找到吗？"],["Let us wish that man will live as long as he can. Though miles apart, we'll share the beauty she displays.","但愿人长久，千里共婵娟。"]]},{"n":98,"t":"圣诞节","sub":"节日","lv":"中级","w":[["Christmas","圣诞节"],["Jesus","耶稣"],["wreath","花环"],["Christmas tree","圣诞树"],["Santa Claus","圣诞老人"],["reindeer","驯鹿"],["chimney","烟囱"],["turkey","火鸡"]],"s":[["Christmas is on December 25th. It's an important religious holiday in Western countries.","圣诞节在12月25日。这是西方国家的一个重要宗教节日。"],["Christmas commemorates the birth of Jesus.","圣诞节是为了纪念耶稣的诞生。"],["Most homes decorate for Christmas with wreaths and Christmas trees.","大多数家庭都用花环和圣诞树来装饰圣诞节。"],["People decorate the Christmas trees with lights and ornaments, topping it with an angel or star.","人们用灯和饰品装饰圣诞树，并用天使或星星做顶饰。"],["Santa Claus is a jolly elderly man with a white beard and wearing red clothes.","圣诞老人是一个快乐的老头，留着白胡子，穿着红色的衣服。"],["Rudolph is the lead reindeer pulling Santa's sleigh.","鲁道夫是领头拉圣诞老人雪橇的驯鹿。"],["Santa Claus enters houses through the chimney to deliver presents.","圣诞老人通过烟囱进入房子送礼物。"],["Turkey is a staple dish for Christmas.","火鸡是圣诞节的主菜。"]]},{"n":99,"t":"过年","sub":"节日","lv":"中级","w":[["clean up","打扫"],["couplet","对联"],["reunion dinner","团圆饭"],["Spring Festival Gala","春晚"],["red envelope","红包"],["firecracker","鞭炮"],["visit","拜访"],["dragon and lion dances","舞龙舞狮"]],"s":[["Before the Spring Festival, people will clean up the house to push out bad luck.","春节前，人们会打扫房子，赶走坏运气。"],["People decorate their homes with red lanterns, couplets, and paper cuttings.","人们用红灯笼、对联和剪纸来装饰家里。"],["On New Year's Eve, families gather and have a big dinner.","在除夕夜，家人们会聚在一起，享用一顿丰盛的晚餐。"],["After dinner, we can watch the Spring Festival Gala, a televised variety show.","晚饭后，我们可以观看春节联欢会，一场电视综艺节目。"],["Elderly people will give red envelopes to younger generations, symbolizing the passing on of good fortune and blessings.","长辈会给晚辈发红包，寓意着传递好运和祝福。"],["Setting off firecrackers is meant to drive away evil spirits and bring good luck.","放鞭炮是为了驱走邪灵，迎来好运。"],["During the Spring Festival, people will visit each other to express New Year greetings.","春节期间，人们会互相拜年，互致新年祝福。"],["Traditional activities, such as dragon and lion dances, stilt walking, have strong local features.","传统活动，如舞龙舞狮、踩高跷，具有浓郁的地方特色。"]]},{"n":100,"t":"元宵节","sub":"节日","lv":"中级","w":[["Lantern Festival","元宵节"],["Tangyuan","汤圆"],["lantern","灯笼"],["lantern riddles","灯谜"],["temple fairs","庙会"],["Yangko dance","秧歌舞"],["stilt","高跷"],["firework","烟花"]],"s":[["Lantern Festival falls on the 15th day of the first lunar month, marking the end of Chinese New Year.","元宵节在农历正月十五，标志着春节的结束。"],["Tangyuan is a traditional food for Lantern Festival, symbolizing reunion and harmony.","汤圆是元宵节的传统食品，象征着团圆和和谐。"],["People make and watch lanterns of different shapes, sizes and colors.","人们制作和欣赏不同形状、尺寸和颜色的灯笼。"],["People will write riddles on lanterns for others to guess.","人们会在灯笼上写上谜语供他人猜。"],["We can go to temple fairs, which are bustling hubs of activity.","我们可以去逛庙会，那里是热闹非凡的活动场所。"],["People will perform the Yangko dance especially in the northeast region of China.","尤其在中国的东北地区，人们会表演秧歌舞。"],["People also perform stilt walking.","人们还会表演高跷。"],["Setting off fireworks is an indispensable activity, and it's also a way to scare away the evil.","放烟花是必不可少的活动，同时烟花也能赶走邪恶。"]]}];
